import os
import requests


class FirestoreDocumentStore:
    def __init__(self, project_id: str, collection: str, api_key: str | None = None):
        self.project_id = project_id
        self.collection = collection
        self.api_key = api_key or os.environ["FIREBASE_WEB_API_KEY"]
        self.base_url = f"https://firestore.googleapis.com/v1/projects/{project_id}/databases/(default)/documents/{collection}"

    def upsert(self, document_id: str, data: dict) -> dict:
        url = f"{self.base_url}/{document_id}"
        params = {"key": self.api_key}
        payload = {"fields": self._to_firestore_fields(data)}
        response = requests.patch(url, params=params, json=payload, timeout=30)
        response.raise_for_status()
        return response.json()

    def _to_firestore_fields(self, value):
        if isinstance(value, dict):
            return {k: self._to_firestore_value(v) for k, v in value.items()}
        raise TypeError("Top-level document data must be a dict")

    def _to_firestore_value(self, value):
        if value is None:
            return {"nullValue": None}
        if isinstance(value, bool):
            return {"booleanValue": value}
        if isinstance(value, int) and not isinstance(value, bool):
            return {"integerValue": str(value)}
        if isinstance(value, float):
            return {"doubleValue": value}
        if isinstance(value, str):
            return {"stringValue": value}
        if isinstance(value, bytes):
            return {"bytesValue": value.decode("utf-8")}
        if isinstance(value, list):
            return {"arrayValue": {"values": [self._to_firestore_value(v) for v in value]}}
        if isinstance(value, dict):
            return {"mapValue": {"fields": {k: self._to_firestore_value(v) for k, v in value.items()}}}
        raise TypeError(f"Unsupported value type: {type(value).__name__}")
